import math

def get_divisors(m):
    """Returns all positive and negative divisors of m."""
    divs = set()
    # Find positive divisors
    for i in range(1, int(math.sqrt(abs(m))) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)

    # Include negative divisors
    if m != 0:
        for d in divs:
            divs.add(-d)
    return sorted(list(divs))

def characterize_g2(n):
    M = 2**n - 1
    divisors = get_divisors(M)

    possible_residues = set()
    for d in divisors:
        # g(2) - 1 = d, so g(2) = 1 + d
        # We look at g(2) mod M
        residue = (1 + d) % M
        possible_residues.add(residue)

    return M, possible_residues

results = {}
for n in [1, 2, 3]:
    M, residues = characterize_g2(n)
    results[n] = {
        "M": M,
        "residues": sorted(list(residues))
    }

print("--- Results for n=1 ---")
print(f"M = 2^1 - 1 = {results[1]['M']}")
print(f"Possible residues for g(2) mod {results[1]['M']}: {results[1]['residues']}")

print("\n--- Results for n=2 ---")
print(f"M = 2^2 - 1 = {results[2]['M']}")
print(f"Possible residues for g(2) mod {results[2]['M']}: {results[2]['residues']}")

print("\n--- Results for n=3 ---")
print(f"M = 2^3 - 1 = {results[3]['M']}")
print(f"Possible residues for g(2) mod {results[3]['M']}: {results[3]['residues']}")

