import math

def count_odd_exponents(m):
    """Counts the number of distinct prime factors of m that have an odd exponent in the prime factorization of m."""
    if m == 1:
        return 0

    counts = {}
    d = 2
    temp_m = m
    while d * d <= temp_m:
        while temp_m % d == 0:
            counts[d] = counts.get(d, 0) + 1
            temp_m //= d
        d += 1
    if temp_m > 1:
        counts[temp_m] = counts.get(temp_m, 0) + 1

    count = 0
    for exponent in counts.values():
        if exponent % 2 != 0:
            count += 1
    return count

def find_nth_m(N):
    """Finds the N-th positive integer m such that the number of distinct prime factors with odd exponent is even."""
    count = 0
    m = 0
    while count < N:
        m += 1
        if count_odd_exponents(m) % 2 == 0:
            count += 1
    return m

# We need the 132nd such integer m.
N_target = 132
