print(f"The {N_target}th integer m is: {m_132}")

def get_prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_m_good(m):
    """Checks if m satisfies the condition: m has an even number of prime factors raised to an odd power."""
    if m == 1:
