def is_prime(k):
    if k < 2:
        return False
    for i in range(2, int(k**0.5) + 1):
        if k % i == 0:
            return False
    return True

def generate_prime_powers(limit):
    prime_powers = set()

    # Primes
    primes = []
    for p in range(2, limit + 1):
        if is_prime(p):
            primes.append(p)
            prime_powers.add(p)

    # Higher powers
    for p in primes:
        power = p * p
        while power <= limit:
            prime_powers.add(power)
            power *= p

    return sorted(list(prime_powers))

# Estimate limit: Based on rough estimation, 5000 should be safe.
LIMIT = 5000
prime_powers = generate_prime_powers(LIMIT)

print(f"Number of prime powers found up to {LIMIT}: {len(prime_powers)}")

# Check if 132nd is within the limit
